   101	    }
   102	
   103	    // Make a copy so we don't mutate the original object
   104	    const iouReportUpdate = {...iouReport};
   105	
   106	    // Let us ensure a valid value before updating the total amount.
   107	    iouReportUpdate.total = iouReportUpdate.total ?? 0;
   108	    iouReportUpdate.unheldTotal = iouReportUpdate.unheldTotal ?? 0;
   109	
   110	    if (actorAccountID === iouReport.ownerAccountID) {
   111	        iouReportUpdate.total += isDeleting ? -amount : amount;
   112	        if (!isOnHold) {
   113	            iouReportUpdate.unheldTotal += isDeleting ? -amount : amount;
   114	        }
   115	    } else {
   116	        iouReportUpdate.total += isDeleting ? amount : -amount;
   117	        if (!isOnHold) {
   118	            iouReportUpdate.unheldTotal += isDeleting ? amount : -amount;
   119	        }
   120	    }
   121	
   122	    if (iouReportUpdate.total < 0) {
   123	        // The total sign has changed and hence we need to flip the manager and owner of the report.
   124	        iouReportUpdate.ownerAccountID = iouReport.managerID;
   125	        iouReportUpdate.managerID = iouReport.ownerAccountID;
   126	        iouReportUpdate.total = -iouReportUpdate.total;
   127	        iouReportUpdate.unheldTotal = -iouReportUpdate.unheldTotal;
   128	    }
   129	
   130	    return iouReportUpdate;
   131	}
